begin;
do $$
declare a uuid:=gen_random_uuid();u uuid:=gen_random_uuid();sport uuid;tid uuid;mid uuid;child uuid;job jsonb;result jsonb;records jsonb;rules jsonb:='[{"unit":"legs","first_to":6,"winner_points":10,"exact_points":15},{"unit":"legs","first_to":6,"winner_points":10,"exact_points":15}]';
begin
 insert into public.user_roles values(a,'admin'),(u,'user');select id into sport from public.sports where slug='darts';
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('role','authenticated',true);
 begin
  perform public.create_knockout_game_with_scores('Bad URL',sport,'players',array['A','B'],null,'[{"unit":"legs","first_to":6,"winner_points":10,"exact_points":15}]','replacement',null,'draft','mastercaller_test','https://evil.invalid/');
  raise exception 'FAIL invalid URL accepted';
 exception when raise_exception then if sqlerrm like 'FAIL%' then raise;end if;end;
 tid:=public.create_knockout_game_with_scores('QA Mastercaller',sport,'players',array['QA A','QA B','QA C'],now()+interval '1 day',rules,'replacement',now()+interval '3 days','draft','mastercaller_test','https://mastercaller.nl/toernooien/swiss-darts-trophy/2026/uitslagen');
 if public.get_tournament_score_source(tid)->>'url'<>'https://mastercaller.com/tournaments/swiss-darts-trophy/2026/results' then raise exception 'FAIL URL canonicalisation';end if;
 perform set_config('role','none',true);
 select match_id into mid from predict_private.knockout_nodes where tournament_id=tid and round_no=1 and not is_bye;
 select match_id into child from predict_private.knockout_nodes where tournament_id=tid and round_no=2;
 perform set_config('role','authenticated',true);
 perform public.edit_knockout(tid,'schedule',mid,jsonb_build_object('start',now()+interval '1 day','unit','legs','first_to',6));
 perform public.edit_knockout(tid,'schedule',child,jsonb_build_object('start',now()+interval '2 days','unit','legs','first_to',6));
 perform public.edit_knockout(tid,'publish');
 perform set_config('request.jwt.claim.sub',u::text,true);perform public.join_tournament(tid);perform public.submit_match_prediction(mid,6,3);
 begin perform public.set_tournament_score_source(tid,'manual');raise exception 'FAIL ordinary user config';exception when insufficient_privilege then null;end;
 begin perform public.finish_mastercaller_job(tid,gen_random_uuid(),'[]');raise exception 'FAIL ordinary user inject';exception when insufficient_privilege then null;end;
 begin perform 1 from predict_private.mastercaller_sources;raise exception 'FAIL direct config read';exception when insufficient_privilege then null;end;
 perform set_config('role','none',true);
 update public.matches set scheduled_start=now()-interval '1 hour',predictions_enabled=false where id=mid;
 records:=jsonb_build_array(jsonb_build_object('depth',1,'round','Semi-finals','home_name','QA C','away_name','QA B','home_score',3,'away_score',6,'date',((now()-interval '1 hour') at time zone 'Europe/Amsterdam')::date));
 job:=public.claim_mastercaller_jobs(tid,a)->0;
 if jsonb_array_length(public.claim_mastercaller_jobs(tid,a))<>0 then raise exception 'FAIL cooldown';end if;
 -- Test invalid dates and formats without touching a real result.
 result:=public.finish_mastercaller_job(tid,(job->>'lease')::uuid,jsonb_set(records,'{0,date}','"2099-01-01"'));
 if (result->>'applied')::int<>0 or jsonb_array_length(result->'issues')<>1 then raise exception 'FAIL future date';end if;
 update predict_private.mastercaller_sources set last_attempt=now()-interval '6 minutes' where tournament_id=tid;
 job:=public.claim_mastercaller_jobs(tid,a)->0;
 result:=public.finish_mastercaller_job(tid,(job->>'lease')::uuid,jsonb_set(records,'{0,away_score}','5'));
 if (result->>'applied')::int<>0 then raise exception 'FAIL wrong score accepted';end if;
 update predict_private.mastercaller_sources set last_attempt=now()-interval '6 minutes' where tournament_id=tid;
 job:=public.claim_mastercaller_jobs(tid,a)->0;
 result:=public.finish_mastercaller_job(tid,(job->>'lease')::uuid,records);
 if (result->>'applied')::int<>1 then raise exception 'FAIL result %',result;end if;
 if (select home_score<>6 or away_score<>3 or status<>'finished' or predictions_enabled from public.matches where id=mid) then raise exception 'FAIL reverse result';end if;
 if not exists(select 1 from predict_private.knockout_nodes where match_id=child and home_slot is not null and away_slot is not null) then raise exception 'FAIL advancement';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('role','authenticated',true);
 if (select earned_points from public.get_tournament_leaderboard(tid) where user_id=u)<>15 then raise exception 'FAIL scoring';end if;
 perform set_config('role','none',true);
 update predict_private.mastercaller_sources set last_attempt=now()-interval '6 minutes' where tournament_id=tid;
 job:=public.claim_mastercaller_jobs(tid,a)->0;
 result:=public.finish_mastercaller_job(tid,(job->>'lease')::uuid,records);
 if (result->>'applied')::int<>0 or (result->>'unchanged')::int<>1 then raise exception 'FAIL idempotency';end if;
 update predict_private.mastercaller_sources set last_attempt=now()-interval '6 minutes' where tournament_id=tid;
 job:=public.claim_mastercaller_jobs(tid,a)->0;
 result:=public.finish_mastercaller_job(tid,(job->>'lease')::uuid,jsonb_set(records,'{0,home_score}','2'));
 if (result->>'applied')::int<>0 or jsonb_array_length(result->'issues')<>1 then raise exception 'FAIL overwrite';end if;
 if (select count(*) from public.match_audit_log where match_id=mid and action='mastercaller_test_result')<>1 then raise exception 'FAIL duplicate audit';end if;
 update predict_private.mastercaller_sources set last_attempt=now()-interval '6 minutes' where tournament_id=tid;
 job:=public.claim_mastercaller_jobs(tid,a)->0;
 perform set_config('role','authenticated',true);perform public.set_tournament_score_source(tid,'manual');perform set_config('role','none',true);
 begin perform public.finish_mastercaller_job(tid,(job->>'lease')::uuid,records);raise exception 'FAIL cancelled lease';exception when raise_exception then if sqlerrm like 'FAIL%' then raise;end if;end;
end $$;
rollback;
